window.kbPageData["views/entry/k-63c2d85fb3976c99"] = {"key":"entry/k-63c2d85fb3976c99","state":{"route":"entry/k-63c2d85fb3976c99"},"node":{"id":"k-63c2d85fb3976c99","mode":"k","title":"分类加法与分步乘法计数原理","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["分类加法计数原理与分步乘法计数原理","分类计数与分步计数的组合"],"qs":["国考 2024 副省级 行测#68","国考 2025 地市级 行测#70"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"directorySummary":"把所有方案分成互不重复且合起来覆盖全部方案的类别时，总数等于各类方案数之和。若每个方案由各步选择唯一确定，且每一步在此前任一种可行选择下都有固定数量的选法，则方案数等于各步选法数之积。","review":{"title":"分类加法与分步乘法计数原理","type":"原理与机制","definition":"把所有方案分成互不重复且合起来覆盖全部方案的类别时，总数等于各类方案数之和。若每个方案由各步选择唯一确定，且每一步在此前任一种可行选择下都有固定数量的选法，则方案数等于各步选法数之积。","explanation":"两条原理可以结合使用。先按影响后续选法数的条件分类，再在满足乘法条件的类别内逐步计数。若同类中后续选法数仍随前一步的结果而变，可以继续细分，再将各分支的方案数相加。","basis":"据关联原题及所列出处编释。","references":[{"source":"count","location":"13.5 乘法计数"}],"related":["k-dba2f598313639fa","k-e9c35702da80f9b6"],"examFocus":{"国考 2024 副省级 行测#68":"按两个课题各分到几队分类，分别计算分组方式和各组符合编号限制的负责人选法。","国考 2025 地市级 行测#70":"按每一步累计得分判断下一题能否答对或答错，再计数始终满足得分下限的序列。"}},"aspects":[{"title":"按分组人数确定负责人选法","uses":[{"unit":"Q1","role":"解题依据","use":"本题选D。甲、乙课题各至少分到2队，按甲组为2队、3队、4队分三类。分组确定后，每组须排除编号最小的队伍，再分别选负责人。三类各有45、80、45种，共170种。","evidence":"每个课题安排一个团队负责，且负责团队不能是该课题所有参与团队中编号最小的团队。","qids":["国考 2024 副省级 行测#68"]}]},{"title":"按累计得分确定后续选法","uses":[{"unit":"Q2","role":"解题依据","use":"本题选B。五道判断题每答完一道都至少得1分，前两题必须答对。第三题答对时，后两题各有两种选择，共4种。第三题答错时，第四题必须答对，第五题有两种选择，共2种。两类合计6种。","evidence":"答完每道题时当前的得分都不低于1分","qids":["国考 2025 地市级 行测#70"]}]}]},"questions":{"国考 2024 副省级 行测#68":{"paper":"国考 2024 副省级 行测","n":68,"mod":"数量关系","src":["a566fec37e508ca7f975.pdf",12],"asrc":["a475ecf57d968bc14cd6.pdf",20],"card":"311c91f777916a91e3618691","links":[{"id":"k-63c2d85fb3976c99","role":"解题依据","why":"每类依次确定分组和两位负责人，各步骤的选法数相乘，互斥类别的方案数相加。"}]},"国考 2025 地市级 行测#70":{"paper":"国考 2025 地市级 行测","n":70,"mod":"数量关系","src":["31f401e91aef8d11365d.pdf",12],"asrc":["8cece062c7c079b53130.pdf",22],"card":"fab203eb755878da09ec0964","links":[{"id":"k-63c2d85fb3976c99","role":"解题依据","why":"互斥情形的方案数相加，同一情形中各步的可选数可按乘法合计。"}]}},"terms":{"k-dba2f598313639fa":{"id":"k-dba2f598313639fa","mode":"k","type":"原理与机制","title":"分步乘法计数原理","qs":[],"count":10},"k-e9c35702da80f9b6":{"id":"k-e9c35702da80f9b6","mode":"k","type":"原理与机制","title":"分类加法计数原理","qs":[],"count":3}},"references":{"count":{"name":"OpenStax《Algebra and Trigonometry 2e》计数原理","url":"https://openstax.org/books/algebra-and-trigonometry-2e/pages/13-5-counting-principles"}},"topics":[],"units":{"k-63c2d85fb3976c99":[["国考 2024 副省级 行测#68"],["国考 2025 地市级 行测#70"]]}};
